"""Franka FR3-style joint impedance (torque) controller, shared by the Panda
gripper and the dex-hand wrappers. Ported from the joint_impedance_controller
branch (tasks/robots/franka_joint_impedance_controller.py @ b244281) with three
fixes:

- GPU support: the env's substep loop never applies qf to the solver
  (sapien_env.py step_action calls no gpu_apply_articulation_qf) and only fetches
  state once after all substeps, so the branch version is silently inert on
  physx_cuda — the arm goes limp. Here every substep fetches fresh qpos and
  explicitly applies qf, mirroring the drive-target flush in panda_smooth.py.
- Implicit damping: the branch applies -Kd*dq explicitly through qf. At
  sim_freq=200 that is discretely unstable for the light wrist joints
  (Kd*dt/I > 2): j7 settles into a 100Hz limit cycle at |v|≈5 rad/s with torque
  pinned at the ±12 Nm clamp (aliases to a constant drift when sampled at 20Hz).
  The real controller survives the same gains via 1kHz + large reflected rotor
  inertia. Here the D term is moved into the PhysX joint drive (stiffness=0,
  damping=Kd), which PhysX integrates implicitly and is unconditionally stable —
  the same mechanism that lets the stock PD controller run Kd=100. Only the
  spring term Kp*(q*-q) goes through qf (clamped to the effort limits); the
  branch's dq low-pass (k_alpha) becomes unnecessary and is dropped.
- Gravity compensation: the real deployment law runs on top of libfranka's
  firmware gravity compensation, which the gello gains assume. ManiSkill already
  emulates this for every agent by disabling gravity on all robot links
  (``balance_passive_force`` defaults True in BaseAgent.set_control_mode), so the
  flag here (``gravity_compensation``, default on) mainly exists to make the
  compensated behavior explicit and to offer a faithful-to-physics off switch,
  which must also disable balance_passive_force at the config-dict level or
  ManiSkill re-disables gravity anyway.

Action semantics are identical to the stock pd_joint_pos arm (absolute joint
targets in radians, ``normalize_action=False``), so demos and checkpoints keep
their action convention.

Multi-arm agents (the dual trapezoid-base wrappers) run two instances of this
controller per substep. The per-substep GPU fetch/apply is idempotent but not
free, so ``gpu_fetch``/``gpu_apply`` let the agent assign sync roles: the first
arm fetches qpos once, the last arm applies qf once (set_qf writes into a
shared buffer, and DictController iterates in insertion order).
"""

from dataclasses import dataclass
from typing import Sequence, Union

import numpy as np
import torch
from gymnasium import spaces

from mani_skill.agents.controllers.base_controller import (
    BaseController,
    ControllerConfig,
)
from mani_skill.utils.structs.types import Array

# From gello_software@efc3f4f:
# ros2/src/franka_fr3_arm_controllers/config/controllers.yaml
FRANKA_FR3_DEPLOYMENT_KP = [240.0, 240.0, 240.0, 240.0, 100.0, 60.0, 20.0]
FRANKA_FR3_DEPLOYMENT_KD = [20.0, 20.0, 20.0, 10.0, 10.0, 10.0, 5.0]

# Franka arm effort limits from the in-repo Panda/Franka URDFs.
FRANKA_ARM_FORCE_LIMIT = [87.0, 87.0, 87.0, 87.0, 12.0, 12.0, 12.0]


class FrankaJointImpedanceController(BaseController):
    """Torque controller matching the deployment Franka joint impedance law.

    The real ROS2 controller computes:

        tau = K * (q_goal - q) + D * (-dq_filtered)

    applied on top of libfranka's gravity compensation. Here the spring term is
    applied as a generalized force (clamped to the real Franka effort limits)
    while the damping term runs through the implicit PhysX joint drive — see the
    module docstring for why explicit -Kd*dq is unstable at sim_freq=200.
    """

    config: "FrankaJointImpedanceControllerConfig"
    sets_target_qpos = False
    sets_target_qvel = False

    def _initialize_action_space(self):
        qlimits = self.articulation.get_qlimits()[0, self.active_joint_indices].cpu().numpy()
        if self.config.lower is not None:
            qlimits[:, 0] = self.config.lower
        if self.config.upper is not None:
            qlimits[:, 1] = self.config.upper
        self.single_action_space = spaces.Box(qlimits[:, 0], qlimits[:, 1], dtype=np.float32)

    def set_drive_property(self):
        # Spring goes through qf; damping runs through the joint drive so PhysX
        # integrates it implicitly (explicit -Kd*dq diverges at sim_freq=200).
        # Drive stiffness stays 0 so there is no second position loop.
        for joint, kd, limit in zip(
            self.joints, self.config.damping, self.config.force_limit
        ):
            joint.set_drive_properties(0.0, kd, force_limit=limit, mode="force")
        # libfranka compensates gravity in firmware below the impedance law;
        # PhysX GPU has no passive-force query, so emulate it by disabling link
        # gravity (same trick as ManiSkill's balance_passive_force default).
        for link in self.articulation.links:
            link.disable_gravity = bool(self.config.gravity_compensation)

    def reset(self):
        super().reset()
        self._target_qpos = self.qpos.clone()
        self._kp = torch.as_tensor(
            self.config.stiffness, dtype=self.qpos.dtype, device=self.device
        ).view(1, -1)
        self._force_limit = torch.as_tensor(
            self.config.force_limit, dtype=self.qpos.dtype, device=self.device
        ).view(1, -1)

    def set_action(self, action: Array):
        action = self._preprocess_action(action)
        self._target_qpos = torch.broadcast_to(action, self.qpos.shape).clone()
        self._apply_impedance_torque()

    def before_simulation_step(self):
        self._apply_impedance_torque()

    def _apply_impedance_torque(self):
        if self.scene.gpu_sim_enabled and self.config.gpu_fetch:
            # the env fetches state only once per control step (after all
            # substeps), so refresh qpos here or the spring runs on stale
            # 20Hz-old state for all 10 substeps
            self.scene.px.gpu_fetch_articulation_qpos()
        torque = self._kp * (self._target_qpos - self.qpos)
        torque = torch.clamp(torque, -self._force_limit, self._force_limit)

        qf = self.articulation.get_qf().clone()
        qf[..., self.active_joint_indices] = torque
        self.articulation.set_qf(qf)
        if self.scene.gpu_sim_enabled and self.config.gpu_apply:
            # the env never applies qf during the substep loop; without this the
            # solver ignores set_qf entirely and the arm is undriven on GPU
            self.scene.px.gpu_apply_articulation_qf()


@dataclass
class FrankaJointImpedanceControllerConfig(ControllerConfig):
    lower: Union[None, float, Sequence[float]] = None
    upper: Union[None, float, Sequence[float]] = None
    stiffness: Sequence[float] = tuple(FRANKA_FR3_DEPLOYMENT_KP)
    damping: Sequence[float] = tuple(FRANKA_FR3_DEPLOYMENT_KD)
    force_limit: Sequence[float] = tuple(FRANKA_ARM_FORCE_LIMIT)
    gravity_compensation: bool = True
    # Sync-role knobs for multi-arm agents: per-substep GPU fetch/apply is
    # idempotent, so both default True; a dual-arm agent sets fetch on the
    # first arm and apply on the last to halve the per-substep sync cost.
    gpu_fetch: bool = True
    gpu_apply: bool = True
    normalize_action: bool = False
    controller_cls = FrankaJointImpedanceController
